    # 其他运行态均不变。失败随整批丢弃，时钟与此前操作一并回滚。
    # O(1)、O(1)。
    _, backend_id, base, target, now = op
    record = backends.get(backend_id)
    if record is None:
        fail(EXIT_BACKEND, "BACKEND")
    current = record["endpoint"]
    if current != target:
        if current != base:
